623	fn generate_predefined_setter(
624	    visibility: Visibility,
625	    name: &'static str,
626	    length: &'static str,
627	    fields: &[TokenStream2],
628	    length_tokens: &TokenStream2,
629	    negate: bool,
630	    doc_string: &str,
631	) -> TokenStream2 {
632	    let (negation_qualifier, negation_token) = if negate {
633	        ("_neg", quote! { - })
634	    } else {
635	        ("", quote! {})
636	    };
637	
638	    let method_name = if length.is_empty() {
639	        format_ident!("{name}{negation_qualifier}")
640	    } else {
641	        format_ident!("{name}{negation_qualifier}_{length}")
642	    };
643	
644	    let field_assignments = fields
645	        .iter()
646	        .map(|field_tokens| {
647	            quote! {
648	                style.#field_tokens = Some((#negation_token gpui::#length_tokens).into());
649	            }
650	        })
651	        .collect::<Vec<_>>();
652	
653	    let method = quote! {
654	        #[doc = #doc_string]
655	        #visibility fn #method_name(mut self) -> Self {
656	            let style = self.style();
657	            #(#field_assignments)*
658	            self
659	        }
660	    };
661	
662	    method
663	}
664	
665	fn generate_custom_value_setter(
666	    visibility: Visibility,
667	    prefix: &str,
668	    length_type: TokenStream2,
669	    fields: &[TokenStream2],
670	    doc_string: &str,
671	) -> TokenStream2 {
672	    let method_name = format_ident!("{}", prefix);
673	
674	    let mut iter = fields.iter();
675	    let last = iter.next_back().unwrap();
676	    let field_assignments = iter
677	        .map(|field_tokens| {
678	            quote! {
679	                style.#field_tokens = Some(length.clone().into());
680	            }
681	        })
682	        .chain(std::iter::once(quote! {
683	            style.#last = Some(length.into());
684	        }))
685	        .collect::<Vec<_>>();
686	
687	    let method = quote! {
688	        #[doc = #doc_string]
689	        #visibility fn #method_name(mut self, length: impl std::clone::Clone + Into<gpui::#length_type>) -> Self {
690	            let style = self.style();
691	            #(#field_assignments)*
692	            self
693	        }
694	    };
695	
696	    method
697	}
